<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import AgentIcon from '@/components/assistant/AgentIcon.vue'
import { visionList, type VisionRecord } from '@/api/vision'
import CropVisionWorkbench from './CropVisionWorkbench.vue'
import FarmRiskCenter from './FarmRiskCenter.vue'
import SoftwareStatus from './SoftwareStatus.vue'
import ObservationHistory from './ObservationHistory.vue'
import type { BusinessModule, DashboardSnapshot, SceneEntity } from '@/types'
const props = defineProps<{ snapshot: DashboardSnapshot | null; entity?: SceneEntity; loading: boolean; error: string }>()
const emit = defineEmits<{ (e:'close'):void; (e:'refresh'):void; (e:'vision'):void; (e:'module',module:BusinessModule):void; (e:'select',id:string):void; (e:'ask',question:string):void }>()
const riskOpen=ref(false)
const tab = ref('observations'), query = ref(''), onlyOpen = ref(true)
const tabs = [{id:'observations',label:'生长监测'},{id:'vision',label:'病虫害识别'},{id:'yield',label:'产量预测'},{id:'risk',label:'风险评估'}]
const pendingCount = computed(() => props.snapshot?.summary.openAlerts || 0)
const openAlerts = computed(() => props.snapshot?.alerts.filter(a=>!['已处理','已恢复'].includes(a.status)) || [])
const rows = computed(() => (props.snapshot?.zones || []).filter(z=>`${z.crop} ${z.stage} ${props.snapshot?.entities.find(e=>e.id===z.entityId)?.name}`.includes(query.value.trim())))
const alertRows = computed(() => onlyOpen.value ? openAlerts.value : props.snapshot?.alerts || [])
const selectedZone = computed(() => props.snapshot?.zones.find(z=>z.entityId===props.entity?.id))
const visionRecords=ref<VisionRecord[]>([])
let statusGeneration=0
watch(()=>[props.snapshot?.generatedAt,props.entity?.id],async()=>{
 const current=++statusGeneration;visionRecords.value=[]
 if(!props.snapshot)return
 try{const records=await visionList(props.snapshot.farmId);if(current===statusGeneration)visionRecords.value=records}catch{}
},{immediate:true})
const latestVision=computed(()=>visionRecords.value.filter(r=>r.plotId===props.entity?.id&&r.result).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0])
const healthScore=computed(()=>props.entity?.health??props.snapshot?.summary.health)
const soilMetric=computed(()=>props.snapshot?.environmentMetrics.find(m=>m.label.includes('土壤湿度')))
const nutrientMetric=computed(()=>props.snapshot?.environmentMetrics.find(m=>m.label.includes('EC')))
const visionStatus=computed(()=>latestVision.value?latestVision.value.result?.detections.length?'发现候选 · 待复核':'未发现检测候选':'暂无检测记录')
const formatNumber = (value:number) => Number.isFinite(value) ? value.toLocaleString('zh-CN',{maximumFractionDigits:1}) : '—'
const formatTime = (value:string) => new Date(value).toLocaleString('zh-CN',{hour12:false})
const ask = () => emit('ask',`分析${props.entity?.name || '当前农场'}的观测数据，核验配置阈值并检索资料。区分农场级与地块级数据，列出依据和缺失观测，不推断盐碱程度或病害概率。`)
function download() {
  if(!props.snapshot)return
  const url=URL.createObjectURL(new Blob([JSON.stringify(props.snapshot,null,2)],{type:'application/json'}))
  const link=document.createElement('a');link.href=url;link.download=`盐田丰语-观测快照-${props.snapshot.farmId}-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(url)
}
</script>

<template>
  <aside class="agriculture-panel" aria-label="农业数据工作面板">
    <header class="panel-head"><div><small>盐田丰语 · 作物详情</small><h1>{{ entity?.name || '农场作物总览' }}</h1></div><button class="panel-icon" aria-label="关闭数据面板" @click="emit('close')"><AgentIcon name="close" :size="18" /></button></header>
    <div v-if="selectedZone" class="crop-profile"><span class="crop-emblem"><AgentIcon name="leaf" :size="32" /></span><div><strong>{{selectedZone.crop}}</strong><span class="crop-badge">作物档案</span><p>{{selectedZone.area}} · {{selectedZone.stage}}</p><small>{{entity?.name}} · {{snapshot?.virtualData?'软件演示':'业务档案'}}</small></div></div>
    <div class="source-strip"><span :class="{ live: !snapshot?.virtualData }"><i />{{ snapshot ? snapshot.virtualData ? '共享演示数据' : '业务数据' : '等待数据' }}</span><button :disabled="loading" @click="emit('refresh')">{{ loading ? '同步中…' : '刷新观测' }}</button></div>
    <p class="sync-time">{{ snapshot ? `快照时间 ${formatTime(snapshot.generatedAt)} · 每 30 秒同步` : '正在读取服务器数据' }}</p>
    <nav class="panel-tabs" aria-label="数据分类"><button v-for="item in tabs" :key="item.id" :aria-pressed="tab===item.id" :class="{ active:tab===item.id }" @click="item.id==='risk' ? riskOpen=true : tab=item.id">{{ item.label }}<span v-if="item.id==='alerts' && pendingCount">{{ pendingCount }}</span></button></nav>
    <div class="data-scroll">
      <div v-if="error" class="data-error" role="alert">{{ error }}<button @click="emit('refresh')">重新同步</button></div>
      <div v-if="!snapshot" class="empty-state"><AgentIcon name="clock" :size="26" /><h2>{{ loading ? '正在同步观测' : '还没有可用快照' }}</h2><p>连接成功后显示地块、环境与设备数据。</p></div>
      <Transition v-else name="content" mode="out-in">
        <section v-if="tab==='observations'" key="observations">
          <div class="section-heading"><h2>基本信息</h2><button @click="emit('module','crops')">查看详情 →</button></div><div class="summary-grid"><div><small>种植面积</small><strong class="compact-value">{{selectedZone?.area||'—'}}</strong></div><div><small>种植品种</small><strong class="compact-value">{{selectedZone?.crop||'多作物'}}</strong></div><div><small>生育阶段</small><strong class="compact-value">{{selectedZone?.stage||'查看地块'}}</strong></div></div>
          <div class="crop-health"><div><span class="health-ring" :style="{background:`conic-gradient(var(--ui-brand) ${(healthScore||0)*3.6}deg,var(--ui-brand-soft) 0)`}"><span>{{healthScore??'—'}}<small v-if="healthScore!=null">分</small></span></span><small>{{entity?.health!=null?'作物档案评分':'农场演示评分'}}</small></div><ul><li><span>生长情况</span><button @click="emit('module','crops')">{{selectedZone?.stage||'未登记'}}</button></li><li><span>病虫害风险</span><button @click="tab='vision'">{{visionStatus}}</button></li><li><span>营养观测</span><b>{{nutrientMetric?`EC ${formatNumber(nutrientMetric.numericValue)} ${nutrientMetric.unit}`:'暂无观测'}}</b></li><li><span>水分观测</span><b>{{soilMetric?`${formatNumber(soilMetric.numericValue)}${soilMetric.unit}`:'暂无观测'}}</b></li></ul></div><p class="status-caption">随快照同步 · 环境为农场级演示观测，评分为软件档案值</p>
          <div v-if="entity && !selectedZone" class="facility-context"><span class="section-label">设施档案</span><strong>{{ entity.metric }}</strong><p>当前为软件设施档案；采后批次在种植模块流转，设施与灌排模块保留模拟执行回执。</p><button @click="emit('ask', `检索${entity?.name || '当前设施'}涉及的鸭梨采后贮藏与分选管理资料，列出适用条件和缺失证据，不声称已创建批次或执行设备操作。`)">检索鸭梨采后资料 <AgentIcon name="arrow" :size="14" /></button></div><div v-if="selectedZone" class="plot-context"><AgentIcon name="leaf" :size="20" /><div><strong>{{ selectedZone.crop }}</strong><small>{{ selectedZone.area }} · {{ selectedZone.stage }}</small></div><button @click="emit('module','crops')">管理档案 <AgentIcon name="chevron" :size="13" /></button></div>
          <div class="section-heading"><h2>当前环境观测</h2><span>农场级数据</span></div>
          <div class="observation-grid"><article v-for="metric in snapshot.environmentMetrics" :key="metric.key"><span>{{ metric.label }}</span><strong>{{ formatNumber(metric.numericValue) }}<small>{{ metric.unit }}</small></strong><time>{{ formatTime(metric.measuredAt) }}</time></article></div>
          <ObservationHistory :farm-id="snapshot.farmId" :updated-at="snapshot.generatedAt" :metrics="snapshot.environmentMetrics" /><button class="row-link" @click="emit('module','environment')">查看配置阈值与环境详情 <AgentIcon name="arrow" :size="16" /></button>
          <div class="data-gap"><AgentIcon name="book" :size="18" /><div><strong>{{ snapshot.farmId === 'yantian-01' ? '盐碱地观测口径' : '盐碱地专项观测待补齐' }}</strong><p>{{ snapshot.farmId === 'yantian-01' ? 'EC 与 pH 为演示样本值；缺少采样深度、土壤质地、盐分剖面和真实连续观测，不能据此推断盐碱程度或病害概率。' : '当前没有土壤专项测量；设备 EC 不等于土壤盐分。' }}</p></div></div>
          <div class="section-heading"><h2>快捷操作</h2></div><div class="crop-actions"><button @click="tab='vision'"><AgentIcon name="leaf" :size="18" /><strong>AI 视觉诊断</strong><small>图片 / 摄像头</small></button><button @click="ask"><AgentIcon name="book" :size="18" /><strong>查看 AI 风险</strong><small>资料与观测分析</small></button><button @click="emit('module','crops')"><AgentIcon name="arrow" :size="18" /><strong>进入作物中心</strong><small>档案与农事记录</small></button></div>
        </section>
        <section v-else-if="tab==='vision'" key="vision"><div class="section-heading"><h2>病虫害识别</h2><span>本地模型</span></div><CropVisionWorkbench embedded :farm-id="snapshot.farmId" :selected-id="entity?.id||null" :plots="snapshot.zones" :names="Object.fromEntries(snapshot.entities.map(e=>[e.id,e.name]))" @close="tab='observations'" @ask="emit('ask',$event)"/></section>
        <section v-else-if="tab==='yield'" key="yield"><div class="section-heading"><h2>产量预测</h2><span>作物评估</span></div><div class="diagnosis-entry"><AgentIcon name="leaf" :size="38"/><h2>从生长记录评估产量</h2><p>当前尚无已校准的产量模型。可登记面积、株数、坐果情况与历史采收量，或让 Agent 分析现有资料和缺失条件。</p><button class="agent-action" @click="emit('module','crops')"><strong>管理生长与采收记录</strong><AgentIcon name="arrow" :size="18"/></button><button class="row-link" @click="emit('ask',`评估${selectedZone?.crop||'当前作物'}在${entity?.name||'当前农场'}的产量预测需要哪些资料，检索依据，不编造产量或预测精度。`)">分析预测所需资料 <AgentIcon name="arrow" :size="16"/></button></div></section>
        <section v-else-if="tab==='plots'" key="plots"><div class="section-heading"><h2>地块与作物档案</h2><button @click="emit('module','crops')">编辑档案</button></div><label class="plot-search"><AgentIcon name="search" :size="16" /><input v-model="query" placeholder="搜索地块、作物或生育期" aria-label="搜索地块档案" /></label><button v-for="zone in rows" :key="zone.id" class="plot-row" :class="{ selected:entity?.id===zone.entityId }" @click="emit('select',zone.entityId)"><span class="plot-glyph"><AgentIcon name="leaf" :size="20" /></span><div><strong>{{ snapshot.entities.find(e=>e.id===zone.entityId)?.name || zone.entityId }}</strong><small>{{ zone.crop }} · {{ zone.area }} · {{ zone.stage }}</small><p>{{ zone.environment }}</p></div><AgentIcon name="chevron" :size="15" /></button><p v-if="!rows.length" class="empty-state">没有匹配的地块</p><div class="data-gap"><div><strong>泊头鸭梨适配</strong><p>可在原地块档案中填写鸭梨品种、面积与生育期。保留现有作物记录；梨叶检测支持图片与本机摄像头；采后批次在种植模块登记并追溯。</p></div></div></section>
        <section v-else-if="tab==='alerts'" key="alerts"><div class="section-heading"><h2>观测异常与复核</h2><label class="alert-filter"><input v-model="onlyOpen" type="checkbox" />仅待处理</label></div><p class="record-range">最近 {{ snapshot.alerts.length }} 条记录 · 当前显示 {{ alertRows.length }} 条{{ onlyOpen ? '待处理' : '历史' }}告警</p><article v-for="item in alertRows" :key="item.id" class="alert-row"><span class="alert-level" :class="item.level">!</span><div><strong>{{ item.title }}</strong><small>{{ item.time }} · {{ item.status }}</small><div class="alert-actions"><button v-if="item.entityId" @click="emit('select',item.entityId || '')">定位对象</button><button @click="emit('ask',`核验告警“${item.title}”的现有数据与资料，说明限制和建议，不执行设备操作。`)">Agent 核验</button></div></div></article><div v-if="!alertRows.length" class="empty-state"><AgentIcon name="check" :size="28" /><h2>最近记录没有{{ onlyOpen ? '待处理' : '' }}告警</h2><p>没有告警不代表已完成病害或盐分风险评估。</p></div><button class="row-link" @click="emit('module','alerts')">进入告警处理中心 <AgentIcon name="arrow" :size="16" /></button></section>
        <section v-else key="readiness"><SoftwareStatus /><div class="section-heading"><h2>方案业务接入状态</h2></div><article v-for="item in [{name:'地块与环境观测',state:'可用 · 演示',detail:'当前快照、地块档案、设备与配置阈值。'},{name:'农业 Agent',state:'已接入',detail:'官方 Harness + Qwen；观测、资料、阈值、视觉与业务记录工具；任务计划、取消、重试和导出。'},{name:'农业证据检索',state:'关键词基线',detail:'维护资料库与软件操作参考，检索结果保留来源与片段。'},{name:'梨叶视觉检测',state:'本地模型',detail:'三类候选、检测框、图片与摄像头采样；历史、人工复核和导出。'},{name:'环境与视觉复核',state:'可用',detail:'EC、pH、配置阈值与视觉候选分开展示；保存人工复核意见。'},{name:'农事与采后追溯',state:'软件闭环',detail:'农事、生长记录；采收、分选、入库、出库；模拟灌排和告警处置回执。'},{name:'植物园 3D 与漫游',state:'可用',detail:'园景导览、地块定位、自动巡场、桥面漫游与画质适配；概念场景坐标。'}]" :key="item.name" class="readiness-row"><div><strong>{{ item.name }}</strong><span>{{ item.state }}</span></div><p>{{ item.detail }}</p></article><button class="row-link" @click="download">导出当前观测快照 <AgentIcon name="external" :size="16" /></button></section>
      </Transition>
    </div>
    <footer><span>观测与建议分开记录</span><button :disabled="!snapshot" title="导出服务器快照" @click="download"><AgentIcon name="external" :size="14" />导出快照</button></footer>
  </aside>
  <FarmRiskCenter v-if="riskOpen && snapshot" :snapshot="snapshot" :entity="entity" @close="riskOpen=false" @ask="emit('ask',$event)"/>
</template>

